import torch


def _flat_to_per_dim_indices(flat_indices, inp_shape):
    strides = []
    prod = 1
    for s in reversed(inp_shape):
        strides.append(prod)
        prod *= s
    strides = tuple(reversed(strides))
    result = []
    for i in range(len(inp_shape)):
        result.append((flat_indices // strides[i]) % inp_shape[i])
    return tuple(result)


def gen_inputs(ctx, device):
    inp_shape = tuple(ctx["inp__shape"])
    dtype = getattr(torch, ctx["inp__dtype"])
    mask_shape = tuple(ctx["mask__shape"])
    inp = torch.randn(inp_shape, dtype=dtype, device=device)
    mask = torch.randint(0, 2, mask_shape, dtype=torch.int32, device=device)
    numel = inp.numel()
    flat_indices = torch.randint(0, max(numel, 1), mask_shape, device=device)
    values = torch.randn(mask_shape, dtype=dtype, device=device)
    indices = _flat_to_per_dim_indices(flat_indices, inp_shape)
    return {"inp": inp, "mask": mask, "indices": list(indices), "values": values}


def run(inp, mask, indices, values):
    return torch._unsafe_masked_index_put_accumulate(inp, mask, list(indices), values)
